@Mod.EventBusSubscriber(modid=Thaumcraft.MODID)
public final class MobilityClient {
 static final BlockPos Q=new BlockPos(600,205,8);static int ticks,stage;static long due;static WorkerGolem g;static SealEntity dest;static ChestBlockEntity chest;static GolemBuilder builder;static double maxHeight;static Vec3 hover;
 static WorkerGolem spawn(ServerPlayer p,int legs,BlockPos q){var w=LogisticsClient.spawn(p,new GolemDesign(3,0,0,3,legs),q);w.setCustomName(Component.literal("Mobility "+legs));w.cargo.setItem(0,new ItemStack(Items.EMERALD,17));return w;}
 static void chest(ServerPlayer p,BlockPos q){dest=GolemClient.chestSeal(p,SealKind.FILL,q);chest=(ChestBlockEntity)p.level().getBlockEntity(q);chest.clearContent();dest.filter=new ItemStack(Items.EMERALD);}
 static void clear(ServerPlayer p){if(dest!=null)GolemClient.remove(dest);if(g!=null)g.discard();for(var q:BlockPos.betweenClosed(Q.offset(-10,0,-10),Q.offset(20,12,10)))p.level().setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());}
 static void snapshot(ServerPlayer p){var d=g.design();var out=TagValueOutput.createWithContext(ProblemReporter.DISCARDING,p.registryAccess());g.saveWithoutId(out);var copy=new WorkerGolem(GolemContent.GOLEM.get(),p.level());copy.load(TagValueInput.create(ProblemReporter.DISCARDING,p.registryAccess(),out.buildResult()));check(copy.design().equals(d)&&copy.cargo.getItem(0).getCount()==17&&copy.isNoGravity(),"Flight snapshot lost cargo/design/gravity");g.discard();copy.setUUID(UUID.randomUUID());g=copy;check(p.level().addFreshEntity(g),"Cannot restore flying worker");}
 @SubscribeEvent public static void tick(TickEvent.ServerTickEvent.Post e){if(!System.getProperty("thaumcraft.thaumaturgyProbe","").equals("mobility-client")||e.server().isDedicatedServer()||e.server().getPlayerList().getPlayers().isEmpty()||++ticks<80)return;var p=e.server().getPlayerList().getPlayers().getFirst();var l=p.level();long now=l.getGameTime();
 if(stage==0){var r=l.recipeAccess().getRecipes().stream().map(h->h.value()).filter(v->v instanceof thaumcraft.crafting.ArcaneRecipe a&&a.research().equals("LEVITATOR")).map(v->(thaumcraft.crafting.ArcaneRecipe)v).findFirst().orElseThrow();var input=net.minecraft.world.item.crafting.CraftingInput.of(3,3,List.of(new ItemStack(Items.OAK_PLANKS),item("plate_thaumium"),new ItemStack(Items.OAK_PLANKS),item("plate_iron"),new ItemStack(net.minecraft.core.registries.BuiltInRegistries.ITEM.getValue(net.minecraft.resources.Identifier.fromNamespaceAndPath("thaumcraft","nitor_pink"))),item("plate_iron"),new ItemStack(Items.OAK_PLANKS),item("mechanism_simple"),new ItemStack(Items.OAK_PLANKS)));check(r.vis()==35&&r.crystals().get("aer")==1&&r.matches(input,l)&&r.assemble(input).is(thaumcraft.devices.DeviceContent.LEVITATOR.get().asItem()),"Native levitator recipe/cost/nitor tag failed");Thaumcraft.LOGGER.info("MOBILITY_LEVITATOR_RECIPE_OK");knowledge(p);p.getInventory().clearContent();p.setGameMode(GameType.SURVIVAL);for(int x=36;x<=39;x++)for(int z=-1;z<=1;z++)l.setChunkForced(x,z,true);for(var w:l.getEntitiesOfClass(WorkerGolem.class,new AABB(Q).inflate(40)))w.discard();clear(p);for(var q:BlockPos.betweenClosed(Q.offset(-10,-1,-10),Q.offset(20,-1,10)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());p.teleportTo(l,Q.getX()-4.5,Q.getY(),Q.getZ()-5.5,Set.of(),0,0,true);chest(p,Q.east(12));stage=1;due=now+60;return;}
 if(stage==1&&now>=due){g=spawn(p,1,Q);check(g.getAttributeValue(Attributes.MOVEMENT_SPEED)>.32&&g.getAttributeValue(Attributes.STEP_HEIGHT)==.5&&!g.noPhysics,"Wheel stats/collision wrong");stage=2;due=now+500;return;}
 if(stage==2){check(now<due,"Wheel delivery timeout "+g.position());if(GolemClient.count(chest,Items.EMERALD)!=17)return;check(g.cargo.isEmpty(),"Wheel duplicated cargo");Thaumcraft.LOGGER.info("MOBILITY_WHEELS_OK: native deployment, collision, speed and 17 physical items delivered");clear(p);for(var q:BlockPos.betweenClosed(Q.offset(4,0,-6),Q.offset(10,5,6)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());chest(p,Q.east(8).above(6));g=spawn(p,2,Q);maxHeight=g.getY();stage=3;due=now+900;return;}
 if(stage==3){maxHeight=Math.max(maxHeight,g.getY());if(now%100==0)Thaumcraft.LOGGER.info("MOBILITY_CLIMB_PROGRESS {} climb={} nav={}",g.position(),g.onClimbable(),g.getNavigation().isDone());check(now<due,"Climber delivery timeout "+g.position()+" max="+maxHeight);if(GolemClient.count(chest,Items.EMERALD)!=17)return;check(maxHeight>=Q.getY()+4&&g.cargo.isEmpty()&&!g.noPhysics,"Climber bypassed wall or lost cargo");Thaumcraft.LOGGER.info("MOBILITY_CLIMBER_OK: climbed six-block solid wall and delivered 17 physical items");clear(p);for(var q:BlockPos.betweenClosed(Q.offset(1,-4,-10),Q.offset(11,-1,10)))l.setBlockAndUpdate(q,Blocks.AIR.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(12,3,-3),Q.offset(16,3,3)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());for(var q:BlockPos.betweenClosed(Q.offset(6,0,-3),Q.offset(6,5,3)))l.setBlockAndUpdate(q,Blocks.STONE.defaultBlockState());chest(p,Q.east(14).above(4));g=spawn(p,3,Q);check(g.isNoGravity()&&g.getNavigation() instanceof GolemNavigation.Hover&&!g.noPhysics,"Flyer navigation/collision wrong");maxHeight=g.getY();stage=4;due=now+900;return;}
 if(stage==4){maxHeight=Math.max(maxHeight,g.getY());check(now<due,"Flyer takeoff timeout "+g.position());if(g.getX()<Q.getX()+2)return;check(g.cargo.getItem(0).getCount()==17,"Flyer lost physical cargo in air");snapshot(p);stage=5;return;}
 if(stage==5){maxHeight=Math.max(maxHeight,g.getY());if(now%100==0)Thaumcraft.LOGGER.info("MOBILITY_FLIGHT_PROGRESS {} nav={}",g.position(),g.getNavigation().isDone());check(now<due,"Flyer delivery timeout "+g.position()+" max="+maxHeight);if(GolemClient.count(chest,Items.EMERALD)!=17)return;check(g.cargo.isEmpty()&&maxHeight>Q.getY()+2&&!g.noPhysics,"Flyer lost cargo or did not ascend");g.setMode(2);hover=g.position();stage=6;due=now+60;return;}
 if(stage==6&&now>=due){check(g.position().distanceToSqr(hover)<.01&&g.isNoGravity(),"Stay flyer drifted/fell");g.cargo.setItem(0,new ItemStack(Items.GOLD_INGOT,11));g.setHealth(4);var d=g.design();p.setItemInHand(InteractionHand.MAIN_HAND,item("golem_bell"));p.setShiftKeyDown(true);check(g.interact(p,InteractionHand.MAIN_HAND,Vec3.ZERO)==InteractionResult.SUCCESS&&g.isRemoved(),"Flyer bell packing failed");p.setShiftKeyDown(false);var pack=java.util.stream.IntStream.range(0,36).mapToObj(i->p.getInventory().getItem(i)).filter(s->s.getItem() instanceof GolemPlacer).findFirst().orElseThrow();check(pack.get(GolemContent.DESIGN.get()).equals(d)&&Math.abs(pack.get(GolemContent.HEALTH.get())-.25F)<.001,"Packed flyer lost design or healed");check(l.getEntitiesOfClass(ItemEntity.class,new AABB(g.blockPosition()).inflate(3),x->x.getItem().is(Items.GOLD_INGOT)&&x.getItem().getCount()==11).size()==1,"Flyer packing lost/duplicated cargo");Thaumcraft.LOGGER.info("MOBILITY_FLIGHT_OK: collision flight across gap and wall, loaded snapshot, 17 delivered, Stay hover and bell cargo/health preserved");GolemClient.remove(dest);l.setBlockAndUpdate(Q.west(3),GolemContent.BUILDER.get().defaultBlockState());builder=(GolemBuilder)l.getBlockEntity(Q.west(3));builder.draft=GolemDesign.BASIC;GolemProbe.giveComponents(p,new GolemDesign(0,0,0,0,3));p.teleportTo(l,Q.getX()-3.5,Q.getY(),Q.getZ()-.5,Set.of(),0,0,true);p.openMenu(builder);stage=7;return;}
 if(stage==7&&builder.working()){check(builder.draft.legs()==3&&!builder.edit(p,5),"Native GUI build did not lock flyer design");Thaumcraft.LOGGER.info("MOBILITY_CLIENT_OK: wheel/climb/flight cargo routes, persistence, packing and native paid GUI job");stage=8;}
 }
}
